<script setup lang="ts">
import { ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { House, Document, Wallet, Files, DataAnalysis, Warning, Checked, Connection, Setting, User, Fold, Expand, Bell, ArrowDown, MagicStick, SwitchButton, TrendCharts, Collection } from '@element-plus/icons-vue'
import { useSession } from '../stores/session'
import { queryClient } from '../api/client'
import { useEvents } from '../composables/useEvents'
import AssistantDrawer from '../components/AssistantDrawer.vue'
const session=useSession(),route=useRoute(),router=useRouter(),assistant=ref(false),notifications=ref(false)
const {connected}=useEvents()
const groups=[{title:'工作空间',items:[{label:'工作台概览',path:'/dashboard',icon:House}]},{title:'票据与账务',items:[{label:'发票中心',path:'/invoices',icon:Document},{label:'智能入账',path:'/posting',icon:MagicStick},{label:'费用报销',path:'/reimbursements',icon:Wallet},{label:'电子档案',path:'/archives',icon:Files}]},{title:'税务与风控',items:[{label:'税务申报',path:'/filings',icon:Collection},{label:'风险管控',path:'/risks',icon:Warning},{label:'合规检查',path:'/compliance',icon:Checked}]},{title:'数据与管理',items:[{label:'财务报表',path:'/reports',icon:TrendCharts},{label:'应用集成',path:'/integrations',icon:Connection},{label:'组织权限',path:'/org',icon:User},{label:'系统设置',path:'/settings',icon:Setting}]}]
watch(()=>session.tenant,()=>{queryClient.clear();if(route.params.id)void router.replace('/invoices')})
async function logout(){await session.logout();await router.replace('/login')}
</script>
<template><div class="workbench" :class="{collapsed:session.collapsed}"><aside class="sidebar"><RouterLink to="/dashboard" class="brand"><span class="brand-mark"><el-icon><DataAnalysis/></el-icon></span><span class="brand-name">税枢云<small>TAXHUB CLOUD</small></span></RouterLink><div class="workspace-label">企业财税工作台 <span>专业版</span></div><nav aria-label="主导航"><section v-for="group in groups" :key="group.title"><p class="nav-group">{{group.title}}</p><RouterLink v-for="item in group.items" :key="item.path" :to="item.path" :title="item.label" class="nav-item" :class="{active:route.path.startsWith(item.path)}"><el-icon><component :is="item.icon"/></el-icon><span>{{item.label}}</span><span v-if="item.path==='/posting'" class="nav-ai">AI</span></RouterLink></section></nav><div class="sidebar-bottom"><div class="secure-mark">◈ <span>数据有据，财税有序<small>本地演示环境 · 合成数据</small></span></div><button class="collapse-button" @click="session.collapsed=!session.collapsed" :aria-label="session.collapsed?'展开导航':'收起导航'"><el-icon><Expand v-if="session.collapsed"/><Fold v-else/></el-icon><span>收起导航</span></button></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb">工作空间 <span>/</span><strong>{{route.meta.title}}</strong></div><div class="top-actions"><el-select v-model="session.tenant" aria-label="当前法人主体" class="tenant-select"><el-option v-for="tenant in session.me?.tenants" :key="tenant.id" :label="tenant.name" :value="tenant.id"/></el-select><button class="assistant-trigger" @click="assistant=true"><el-icon><MagicStick/></el-icon> AI 助手</button><button class="icon-button notification-button" aria-label="通知中心" @click="notifications=true"><el-icon><Bell/></el-icon><i/></button><el-dropdown @command="logout"><button class="profile"><span class="avatar">{{session.me?.role==='viewer'?'访':'林'}}</span><span>{{session.me?.name}}</span><el-icon><ArrowDown/></el-icon></button><template #dropdown><el-dropdown-menu><el-dropdown-item :icon="SwitchButton" command="logout">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header><main class="page-content"><RouterView :key="`${session.tenant}:${route.path.startsWith('/invoices')?'/invoices':route.path}`" /></main><footer class="app-footer"><span>税枢云 · 让每一笔业务清晰可溯</span><span :class="{offline:!connected}"><i/>{{connected?'演示服务已连接':'实时连接重连中'}} · v0.1</span></footer></div><AssistantDrawer v-model="assistant"/><el-drawer v-model="notifications" title="通知中心" size="min(400px,100vw)"><div class="notice-card"><strong>欢迎使用税枢云演示工作台</strong><p>本轮可体验模拟采集、查验、入账建议、凭证查看和风险处置。</p><small>所有数据均为合成样例，不产生真实财税结果。</small></div></el-drawer></div></template>
